7	  int<lower=1> N_items;
8	  array[N_models, N_items] int<lower=0, upper=1> y;
9	  matrix[N_models, N_items] exposure;
10	}
11	
12	parameters {
13	  vector[N_models] theta;
14	  vector<lower=0>[N_items] a;
15	  vector[N_items] b;
16	  vector<lower=0.001, upper=0.999>[N_items] c;
17	  vector<lower=0.001, upper=0.999>[N_items] d;
18	  real gamma;
19	}
