21	model {
22	  // Priors
23	  theta ~ std_normal();
24	  a ~ lognormal(0, 0.5);
25	  b ~ std_normal();
26	  c ~ beta(5, 20);
27	  d ~ beta(20, 5);
28	  gamma ~ std_normal();
29	
30	  // Likelihood
31	  for (i in 1:N_models) {
32	    for (j in 1:N_items) {
33	      real eta = a[j] * (theta[i] - b[j]) + gamma * exposure[i, j];
34	      real p = c[j] + (d[j] - c[j]) * inv_logit(eta);
35	      y[i, j] ~ bernoulli(p);
36	    }
37	  }
38	}
