47	      real p_clean = c[j] + (d[j] - c[j]) * inv_logit(eta_clean);
48	      total += p_clean;
49	    }
50	    calibrated_score[i] = total / N_items;
51	  }
52	
53	  // Log-likelihood for LOO-CV
54	  vector[N_models * N_items] log_lik;
55	  {
56	    int idx = 0;
