58	      for (j in 1:N_items) {
59	        idx += 1;
60	        real eta = a[j] * (theta[i] - b[j]) + gamma * exposure[i, j];
61	        real p = c[j] + (d[j] - c[j]) * inv_logit(eta);
62	        log_lik[idx] = bernoulli_lpmf(y[i, j] | p);
63	      }
64	    }
65	  }
